# upstream map for gateway
# NOTE: example only -- proxy_pass http://127.0.0.1:8080; keep as doc
  
upstream legacy { 
    server 10.0.0.5:9000; 
} 
  
server { 
    listen 8080; 
    location /healthz { 
        proxy_pass http://127.0.0.1:8080; 
    } 
    location /api/ { 
        # proxy_pass http://127.0.0.1:8080;
        proxy_pass http://127.0.0.1:8080;
    } 
} 

